"""Render source-faithful reports from computed evidence. No model execution."""
import json
from pathlib import Path
import pandas as pd
from atlas import ROOT,RESULT,RULES

PIN=RULES['upstream_commit']
BASE='https://github.com/magaliparrino/StrAD/blob/'+PIN+'/'


def load(name):return json.loads((RESULT/name).read_text())


def table(frame,columns=None,limit=None):
    if columns:frame=frame[columns]
    if limit:frame=frame.head(limit)
    def value(v):
        if isinstance(v,(list,tuple)):return ', '.join(map(str,v)) or 'none'
        if pd.isna(v):return 'unknown / unsupported'
        if isinstance(v,float):return f'{v:.5f}'
        return str(v).replace('|',' / ')
    return '\n'.join(['| '+' | '.join(map(str,frame.columns))+' |','|'+'|'.join(['---']*len(frame.columns))+'|']+['| '+' | '.join(value(v) for v in row)+' |' for row in frame.itertuples(index=False,name=None)])


def write(name,lines):(ROOT/name).write_text('\n\n'.join(lines)+'\n')


